// Generates src/features/marketing/content/source-directory.data.ts from seed/source-packs.json:
// a compact, public-safe slice of the seed (name, site domain, kind, types, country, verified count,
// pack, page URL) for the public /packs directory. No API bodies, headers or detection notes ship.
//
//   node apps/web/scripts/gen-source-directory.mjs
//
// The marketing unit test (source-directory.test.ts) fails if the generated file drifts from the seed.
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const seedPath = join(here, '../../../seed/source-packs.json');
const outPath = join(here, '../src/features/marketing/content/source-directory.data.ts');

const ATS = new Set(['greenhouse', 'lever', 'ashby', 'smartrecruiters', 'workable', 'workday']);
const TYPE_ORDER = [
  'internship',
  'fulltime',
  'hackathon',
  'scholarship',
  'fellowship',
  'research',
  'opensource',
];

/** The company or programme site, never the ATS host (DESIGN §7). */
function domainOf(source) {
  if (source.companyDomain) return source.companyDomain.replace(/^www\./, '');
  if (ATS.has(source.kind)) return null;
  try {
    return new URL(source.url).hostname.replace(/^www\./, '');
  } catch {
    return null;
  }
}

const seed = JSON.parse(await readFile(seedPath, 'utf8'));
const packs = seed.packs.map((p) => ({ id: p.id, name: p.name, optional: Boolean(p.optional) }));
const rows = [];
seed.packs.forEach((pack, packIndex) => {
  for (const s of pack.sources) {
    const mask = (s.types ?? []).reduce((m, t) => {
      const bit = TYPE_ORDER.indexOf(t);
      return bit < 0 ? m : m | (1 << bit);
    }, 0);
    rows.push([
      s.name,
      domainOf(s),
      s.kind,
      mask,
      s.country ?? 'GLOBAL',
      typeof s.verifiedCount === 'number' ? s.verifiedCount : null,
      packIndex,
      s.url,
    ]);
  }
});

const header = `/**
 * GENERATED by apps/web/scripts/gen-source-directory.mjs from seed/source-packs.json (${seed.generatedAt}).
 * Do not edit by hand: change the seed, then run \`node apps/web/scripts/gen-source-directory.mjs\`.
 * Row tuple: [name, siteDomain, kind, typeMask, country, verifiedCount, packIndex, url].
 * typeMask bits follow DIRECTORY_TYPES. verifiedCount = postings the endpoint returned on the verification date.
 */
`;
const body = `${header}
export const DIRECTORY_GENERATED_AT = ${JSON.stringify(seed.generatedAt)};
export const DIRECTORY_TYPES = ${JSON.stringify(TYPE_ORDER)} as const;
export const DIRECTORY_PACKS = ${JSON.stringify(packs, null, 2)} as const;
export type DirectoryRow = readonly [string, string | null, string, number, string, number | null, number, string];
export const DIRECTORY_ROWS: readonly DirectoryRow[] = [
${rows.map((r) => `  ${JSON.stringify(r)},`).join('\n')}
];
`;
await writeFile(outPath, body);
console.log(`wrote ${rows.length} sources in ${packs.length} packs → ${outPath}`);
